MK = {"on": 0, "chunk": 25, "slope": 0.75, "base": 28.0, "d0": 2, "d1": 23, "intraday": 0, "cash_floor": 9000.0}
_MKP = {'pos': 0, 'pend': None, 'ref': None}

def _maker(mk, obs, day, hr, money):
    # reactive wheat scalper: the town consumes ~30 wheat every 4h
    # (price ticks up ~$1); sell into that spike, buy back in the calm.
    # Net-flat intraday where possible; reconcile via public money.
    if not MK['on']:
        return mk
    try:
        wp = obs['market']['prices']['WHEAT']
    except Exception:
        return mk
    st = _MKP
    if st['pend'] is not None and st['ref'] is not None:
        kind, ch, px = st['pend']
        st['pend'] = None
        dm = money - st['ref']
        if kind == 'S' and dm >= ch * px * 0.6:
            st['pos'] -= ch
        elif kind == 'B' and dm <= -ch * px * 0.6:
            st['pos'] += ch
        # else: order failed silently (shed/cash) -> no state change
    st['ref'] = money
    if day > MK['d1']:
        # endgame: liquidate any held chunk at a nonzero margin
        if st['pos'] > 0 and hr in (4, 8, 12, 16, 20) and wp >= 30:
            mk.append(['SELL', 'WHEAT', st['pos']])
            st['pend'] = ('S', st['pos'], wp)
        return mk
    if day < MK['d0']:
        return mk
    trend = MK['base'] + MK['slope'] * day
    if hr in (4, 8, 12, 16, 20):
        if st['pos'] >= MK['chunk'] and wp >= trend + 1:
            mk.append(['SELL', 'WHEAT', MK['chunk']])
            st['pend'] = ('S', MK['chunk'], wp)
    elif MK.get('intraday'):
        # intraday-only: buy late morning, flat again by H20; the
        # stock never occupies the shed at EOD (no harvest discards)
        _floor = float(MK.get('cash_floor', 9000))
        if 10 <= hr <= 11 and st['pos'] < MK['chunk']:
            if wp <= trend - 2 and money >= _floor + MK['chunk'] * (wp + 2):
                mk.append(['BUY_PRODUCT', 'WHEAT', MK['chunk']])
                st['pend'] = ('B', MK['chunk'], wp)
        elif st['pos'] > 0 and hr in (12, 16, 20) and wp >= trend - 1:
            mk.append(['SELL', 'WHEAT', st['pos']])
            st['pend'] = ('S', st['pos'], wp)
        elif 21 <= hr <= 22 and st['pos'] > 0:
            mk.append(['SELL', 'WHEAT', st['pos']])
            st['pend'] = ('S', st['pos'], wp)
    elif 10 <= hr <= 18 and st['pos'] < MK['chunk']:
        _floor = float(MK.get('cash_floor', 9000))
        if wp <= trend - 2 and money >= _floor + MK['chunk'] * (wp + 2):
            mk.append(['BUY_PRODUCT', 'WHEAT', MK['chunk']])
            st['pend'] = ('B', MK['chunk'], wp)
    return mk

def agent(obs, configuration=None):
    try:
        step = int(obs.get('step', 0) or 0)
    except Exception:
        step = 0
    t = TAPE[min(step, len(TAPE) - 1)]
    farm_hands = 0
    money = 0
    try:
        seat = 1 if int(obs.get('player', 0) or 0) == 1 else 0
        farms = obs.get('farms', []) or []
        farm_hands = len(farms[seat].get('hands', [])) if seat < len(farms) else 0
        try:
            money = float(farms[seat].get('money', 0) or 0)
        except Exception:
            pass
    except Exception:
        pass
    rows = list(t.get('hands', []))
    if len(rows) > farm_hands:
        rows = rows[:farm_hands]
    elif len(rows) < farm_hands:
        rows = rows + [['PASS']] * (farm_hands - len(rows))
    mk = list(t.get('market', []))
    if len(mk) < 10:
        mk = _maker(mk, obs, step // 24, step % 24, money)
    if (step % 24) in (0, 23):
        mk = _milk_gate(mk, obs, step // 24)
    return {'farmer': t.get('farmer', ['PASS']), 'hands': rows,
            'market': mk}
MG = {"on": 0, "gate": 170.0, "cap": 40, "days": 28}
_MST = {'skipped': 0}

def _milk_gate(mk, obs, day):
    # the town's shop draws are a per-seed lottery; when few
    # milk-draining shops unlock, dumping the planned volume crashes
    # the shared milk price to single digits. The realized price is
    # public: hold the pile when it is below the gate, trickle only
    # the overflow above the shed-safety cap, and release the whole
    # backlog the first morning the price recovers.
    if not MG['on']:
        return mk
    try:
        mp = obs['market']['prices']['MILK']
    except Exception:
        return mk
    out = []
    for o in mk:
        if (isinstance(o, list) and len(o) >= 3 and o[0] == 'SELL'
                and o[1] == 'MILK'):
            if day >= MG['days']:
                o = ['SELL', 'MILK', 99]
                _MST['skipped'] = 0
            elif mp >= MG['gate']:
                q = int(o[2]) + _MST['skipped']
                _MST['skipped'] = 0
                o = ['SELL', 'MILK', q]
            else:
                over = int(o[2]) + _MST['skipped'] - MG['cap']
                if over > 0:
                    _MST['skipped'] = MG['cap']
                    o = ['SELL', 'MILK', over]
                else:
                    _MST['skipped'] += int(o[2])
                    o = None
        if o is not None:
            out.append(o)
    return out
